#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 K, P;
    cin >> K >> P;

    int64 ans = 0;
    int64 powerOfNine = 1;

    for (int length = 1; length <= 7 && K > 0; ++length) {
        int64 leadingChoices = (length == 7 ? 5 : 9);
        int64 count = leadingChoices * powerOfNine;
        int64 take = min(K, count);

        for (int64 rank = 0; rank < take; ++rank) {
            int digits[7];
            int64 value = rank;

            for (int i = length - 1; i >= 0; --i) {
                digits[i] = static_cast<int>(value % 9) + 1;
                value /= 9;
            }

            int64 palindrome = 0;
            for (int i = 0; i < length; ++i)
                palindrome = palindrome * 10 + digits[i];
            for (int i = length - 1; i >= 0; --i)
                palindrome = palindrome * 10 + digits[i];

            ans = static_cast<int64>((static_cast<i128>(ans) + palindrome) % P);
        }

        K -= take;
        powerOfNine *= 9;
    }

    cout << ans;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<ll> current;
    vector<ll> values;
    current.reserve(9);
    values.reserve(3255075);

    for (ll digit = 1; digit <= 9; ++digit) {
        current.push_back(digit * 11);
    }
    values.insert(values.end(), current.begin(), current.end());

    ll place = 1000;
    for (int length = 4; length <= 14; length += 2) {
        int maxDigit = (length == 14 ? 5 : 9);

        vector<ll> next;
        next.reserve(current.size() * maxDigit);

        for (ll palindrome : current) {
            for (ll digit = 1; digit <= maxDigit; ++digit) {
                next.push_back(digit * place + palindrome * 10 + digit);
            }
        }

        values.insert(values.end(), next.begin(), next.end());
        current = move(next);
        place *= 100;
    }

    sort(values.begin(), values.end());

    ll K, P;
    cin >> K >> P;

    ll answer = 0;
    for (ll i = 0; i < K; ++i) {
        answer = (answer + values[i]) % P;
    }

    cout << answer;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll K, P;
    cin >> K >> P;

    ll count = 0;
    ll ans = 0;

    function<void(int, int, ll)> generate = [&](int pos, int len, ll half) {
        if (count >= K) return;

        if (pos == len) {
            ll palindrome = half;
            ll value = half;

            for (int i = 0; i < len; ++i) {
                palindrome = palindrome * 10 + value % 10;
                value /= 10;
            }

            ans = (ll)(((i128)ans + palindrome) % P);
            ++count;
            return;
        }

        int maxDigit = (pos == 0 && len == 7) ? 5 : 9;
        for (int digit = 1; digit <= maxDigit && count < K; ++digit) {
            generate(pos + 1, len, half * 10 + digit);
        }
    };

    for (int len = 1; len <= 7 && count < K; ++len) {
        generate(0, len, 0);
    }

    cout << ans;
    return 0;
}

